# -*- coding: utf-8 -*-

import base64, zlib, marshal, sys

def triple_xor_decrypt(data, key3):
    key1 = 0x5A
    key2 = 0x37
    data = bytes(b ^ key3 for b in data)
    data = bytes(b ^ key2 for b in data)
    data = bytes(b ^ key1 for b in data)
    return data

try:
    data = base64.b64decode("")
    data = triple_xor_decrypt(data, 114)
    data = zlib.decompress(data)
    data = zlib.decompress(data)

    try:
        code_obj = marshal.loads(data)
        exec(code_obj)
    except:
        exec(data.decode("utf-8", errors="ignore"))
except:
    print("Error decoding protection")
    sys.exit(1)

